// QueryInitiative queries the initiative edge of a Phase.
func (c *PhaseClient) QueryInitiative(_m *Phase) *InitiativeQuery {
	query := (&InitiativeClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(phase.Table, phase.FieldID, id),
			sqlgraph.To(initiative.Table, initiative.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, phase.InitiativeTable, phase.InitiativeColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

